package org.beyondlight;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.io.*;import java.time.*;
/** Preliminary machine-component store and SI resource aggregation. */
public final class MachineDesign {
 public record Component(String id,String name,String function,double volumeM3,String materialId,double powerW,double durationS,double heatW,double loadN,double areaM2,List<String>dependencies,String manufacturing,String created){}
 public record Assembly(double massKg,double powerW,double energyJ,double heatW,List<String>missing,List<String>dependencyErrors,int components,String classification){}
 private final Path path;private final MaterialDatabase materials;public MachineDesign(Path p,MaterialDatabase m){path=p;materials=m;}
 public List<Component>all(){try{List<Component>o=new ArrayList<>();if(Files.exists(path))for(String l:Files.readAllLines(path))if(!l.isBlank())o.add(read(Json.map(Json.parse(l))));return o;}catch(IOException e){throw new IllegalStateException("component store read failed");}}
 public Component add(String name,String fn,double volume,String mat,double power,double duration,double heat,double load,double area,String deps,String manufacturing){if(name.isBlank())throw new IllegalArgumentException("component name required");for(double x:new double[]{volume,power,duration,heat,load,area})if(!Double.isFinite(x)||x<0)throw new IllegalArgumentException("component values must be finite and nonnegative");if(!mat.isBlank())materials.find(mat);List<String>ds=deps.isBlank()?List.of():Arrays.stream(deps.split(",")).map(String::trim).filter(x->!x.isBlank()).toList();Component c=new Component(UUID.randomUUID().toString(),name,fn,volume,mat,power,duration,heat,load,area,ds,manufacturing,Instant.now().toString());List<Component>a=all();a.add(c);write(a);return c;}
 public Assembly assemble(){List<Component>cs=all();Set<String>ids=new HashSet<>();cs.forEach(c->ids.add(c.id));List<String>missing=new ArrayList<>(),bad=new ArrayList<>();double mass=0,power=0,energy=0,heat=0;for(Component c:cs){power+=c.powerW;energy+=c.powerW*c.durationS;heat+=c.heatW;if(c.volumeM3>0){if(c.materialId.isBlank())missing.add(c.name+": material missing");else{MaterialDatabase.Material m=materials.find(c.materialId);if(m.densityKgM3()==null)missing.add(c.name+": density missing");else mass+=c.volumeM3*m.densityKgM3();}}if(c.loadN>0){if(c.areaM2==0)missing.add(c.name+": loaded area missing; stress unknown");else if(c.materialId.isBlank())missing.add(c.name+": material yield property missing; stress capacity unevaluated");else if(materials.find(c.materialId).yieldPa()==null)missing.add(c.name+": yield strength unavailable; stress capacity unevaluated (calculated axial stress "+(c.loadN/c.areaM2)+" Pa)");else if(c.loadN/c.areaM2>materials.find(c.materialId).yieldPa())missing.add(c.name+": axial stress exceeds supplied yield strength");}for(String d:c.dependencies)if(!ids.contains(d))bad.add(c.name+": unresolved dependency "+d);}if(!Double.isFinite(mass)||!Double.isFinite(power)||!Double.isFinite(energy)||!Double.isFinite(heat))throw new IllegalArgumentException("aggregate exceeds finite numerical range");String classification=!bad.isEmpty()?"DEPENDENCY ERRORS":!missing.isEmpty()?"INCOMPLETE — MISSING DATA":"PRELIMINARY ESTIMATE — NOT A BUILD CERTIFICATION";return new Assembly(mass,power,energy,heat,List.copyOf(missing),List.copyOf(bad),cs.size(),classification);}
 private void write(List<Component>cs){try{Files.createDirectories(path.getParent());String s=String.join("\n",cs.stream().map(c->Json.stringify(map(c))).toList());Files.writeString(path,s+(s.isEmpty()?"":"\n"),StandardCharsets.UTF_8);}catch(IOException e){throw new IllegalStateException("component save failed");}}
 private static Map<String,Object>map(Component c){Map<String,Object>m=new LinkedHashMap<>();m.put("id",c.id);m.put("name",c.name);m.put("function",c.function);m.put("volumeM3",c.volumeM3);m.put("materialId",c.materialId);m.put("powerW",c.powerW);m.put("durationS",c.durationS);m.put("heatW",c.heatW);m.put("loadN",c.loadN);m.put("areaM2",c.areaM2);m.put("dependencies",c.dependencies);m.put("manufacturing",c.manufacturing);m.put("created",c.created);return m;}
 @SuppressWarnings("unchecked")private static Component read(Map<String,Object>m){return new Component((String)m.get("id"),(String)m.get("name"),(String)m.get("function"),((Number)m.get("volumeM3")).doubleValue(),(String)m.get("materialId"),((Number)m.get("powerW")).doubleValue(),((Number)m.get("durationS")).doubleValue(),((Number)m.get("heatW")).doubleValue(),((Number)m.get("loadN")).doubleValue(),((Number)m.get("areaM2")).doubleValue(),(List<String>)m.get("dependencies"),(String)m.get("manufacturing"),(String)m.get("created"));}
}
